
.rule-modifier {
  display: flex;
  width: 100%;
  height: var(--ui-max-height, 100%);
  max-width: var(--ui-max-width, 900px);
  max-height: var(--ui-max-height, 100%);
  margin: 0 auto;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: calc(14px * var(--ui-scale, 1));
  line-height: 1.5;

  // 全局CSS变量，用于整体UI缩放
  --space-xs: calc(4px * var(--ui-scale, 1));
  --space-sm: calc(8px * var(--ui-scale, 1));
  --space-md: calc(12px * var(--ui-scale, 1));
  --space-lg: calc(16px * var(--ui-scale, 1));
  --space-xl: calc(24px * var(--ui-scale, 1));
  --space-2xl: calc(32px * var(--ui-scale, 1));
  --radius-sm: calc(6px * var(--ui-scale, 1));
  --radius-md: calc(8px * var(--ui-scale, 1));
  --radius-lg: calc(12px * var(--ui-scale, 1));
  --radius-xl: calc(16px * var(--ui-scale, 1));
  --sidebar-width: calc(80px * var(--ui-scale, 1));
  --sidebar-width-wide: calc(240px * var(--ui-scale, 1));
  --middle-panel-width: calc(700px * var(--ui-scale, 1));

  @media (min-width: 1024px) {
    --sidebar-width: var(--sidebar-width-wide);
  }

  &.dark {
    background: #030303;
    color: #f4f4f5;
  }

  &.light {
    background: #f4f4f5;
    color: #18181b;
  }
}

// Sidebar
.sidebar {
  width: var(--sidebar-width);
  height: 100%;
  max-height: var(--ui-max-height, 600px);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.02);
  overflow: hidden;
}

.dark .sidebar {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .sidebar {
  border-color: rgba(0, 0, 0, 0.05);
  background: rgba(255, 255, 255, 0.6);
}

.sidebar-top {
  .logo {
    height: calc(80px * var(--ui-scale, 1));
    display: flex;
    align-items: center;
    justify-content: center;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    gap: var(--space-md);
    padding: 0 var(--space-xl);

    i {
      font-size: calc(24px * var(--ui-scale, 1));
    }

    .logo-text {
      display: none;
      font-weight: 600;
      letter-spacing: 0.15em;
      font-size: calc(16px * var(--ui-scale, 1));

      @media (min-width: 1024px) {
        display: block;
      }
    }
  }

  .nav-items {
    padding: var(--space-lg);
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
  }
}

.dark .sidebar-top .logo {
  border-color: rgba(255, 255, 255, 0.05);
  color: #f4f4f5;
}

.light .sidebar-top .logo {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;
}

.sidebar-bottom {
  padding: var(--space-lg);
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.dark .sidebar-bottom {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .sidebar-bottom {
  border-color: rgba(0, 0, 0, 0.05);
}

.nav-btn {
  display: flex;
  align-items: center;
  padding: var(--space-md);
  border-radius: var(--radius-lg);
  transition: all 0.3s ease;
  position: relative;
  background: transparent;
  border: none;
  cursor: pointer;
  gap: var(--space-md);
  width: 100%;

  i {
    font-size: calc(18px * var(--ui-scale, 1));
    width: calc(24px * var(--ui-scale, 1));
    text-align: center;
  }

  .nav-label {
    display: none;
    font-size: calc(14px * var(--ui-scale, 1));
    font-weight: 500;

    @media (min-width: 1024px) {
      display: block;
    }
  }

  &:hover {
    background: rgba(255, 255, 255, 0.05);
  }

  &.active {
    background: rgba(255, 255, 255, 0.1);

    .active-indicator {
      position: absolute;
      left: 0;
      width: calc(4px * var(--ui-scale, 1));
      height: calc(32px * var(--ui-scale, 1));
      background: currentColor;
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    }
  }
}

.dark .nav-btn {
  color: #a1a1aa;

  &:hover {
    color: #e4e4e7;
    background: rgba(255, 255, 255, 0.05);
  }

  &.active {
    color: #fff;
    box-shadow: 0 0 15px rgba(255, 255, 255, 0.05);
  }
}

.light .nav-btn {
  color: #71717a;

  &:hover {
    color: #18181b;
    background: rgba(0, 0, 0, 0.05);
  }

  &.active {
    color: #000;
    background: rgba(0, 0, 0, 0.05);
    box-shadow: 0 0 15px rgba(0, 0, 0, 0.05);
  }
}

// Middle Panel
.middle-panel {
  width: var(--middle-panel-width);
  height: 100%;
  max-height: var(--ui-max-height, 600px);
  flex-shrink: 0;
  overflow: hidden;
  box-shadow: 0 0 calc(40px * var(--ui-scale, 1)) rgba(0, 0, 0, 0.3);
  z-index: 20;
  animation: slideIn 0.3s ease;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.dark .middle-panel {
  background: #080808;
  border-color: rgba(255, 255, 255, 0.05);
}

.light .middle-panel {
  background: #fff;
  border-color: rgba(0, 0, 0, 0.05);
}

.panel-inner {
  width: var(--middle-panel-width);
  height: 100%;
  display: flex;
  flex-direction: column;
}

.panel-header {
  height: calc(80px * var(--ui-scale, 1));
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 calc(40px * var(--ui-scale, 1));
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(255, 255, 255, 0.02);

  h1 {
    font-size: calc(24px * var(--ui-scale, 1));
    font-weight: 300;
    letter-spacing: 0.05em;
  }

  .close-btn {
    padding: var(--space-sm);
    border-radius: 50%;
    background: transparent;
    border: none;
    cursor: pointer;
    transition: all 0.2s;

    &:hover {
      background: rgba(255, 255, 255, 0.1);
    }
  }
}

.dark .panel-header {
  border-color: rgba(255, 255, 255, 0.05);
  color: #fff;

  .close-btn {
    color: #a1a1aa;

    &:hover {
      color: #fff;
    }
  }
}

.light .panel-header {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;
  background: rgba(255, 255, 255, 0.6);

  .close-btn {
    color: #71717a;

    &:hover {
      color: #18181b;
    }
  }
}

.panel-content {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-xl) calc(40px * var(--ui-scale, 1));
}

.fade-enter-active,
.fade-leave-active {
  transition: all 0.3s ease;
}

.fade-enter-from {
  opacity: 0;
  transform: translateY(15px);
}

.fade-leave-to {
  opacity: 0;
  transform: translateY(-15px);
}

// Main Panel
.main-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 10;
  overflow: hidden;
  height: 100%;
  max-height: var(--ui-max-height, 600px);
}

.dark .main-panel {
  background: #030303;
}

.light .main-panel {
  background: #fafafa;
}

.main-header {
  height: calc(80px * var(--ui-scale, 1));
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 calc(32px * var(--ui-scale, 1));

  .header-title {
    display: flex;
    align-items: center;
    gap: var(--space-md);

    i {
      font-size: calc(24px * var(--ui-scale, 1));
    }

    h2 {
      font-size: calc(18px * var(--ui-scale, 1));
      font-weight: 500;
      letter-spacing: 0.05em;
    }
  }
}

.dark .main-header {
  border-color: rgba(255, 255, 255, 0.05);

  .header-title {
    i { color: #d4d4d8; }
    h2 { color: #fff; }
  }
}

.light .main-header {
  border-color: rgba(0, 0, 0, 0.05);

  .header-title {
    i { color: #52525b; }
    h2 { color: #18181b; }
  }
}

.header-btn {
  background: transparent;
  border: none;
  font-size: calc(20px * var(--ui-scale, 1));
  cursor: pointer;
  transition: color 0.2s;
}

.dark .header-btn {
  color: #71717a;

  &:hover { color: #fff; }
}

.light .header-btn {
  color: #a1a1aa;

  &:hover { color: #18181b; }
}

.header-actions {
  display: flex;
  gap: var(--space-sm);
}

.header-btn.active {
  color: #3b82f6;
}

.dark .header-btn.active {
  color: #60a5fa;
}

.light .header-btn.active {
  color: #2563eb;
}

.header-btn-recover {
  color: #f59e0b;
}

.dark .header-btn-recover {
  color: #fbbf24;

  &:hover {
    color: #fde68a;
  }
}

.light .header-btn-recover {
  color: #d97706;

  &:hover {
    color: #b45309;
  }
}

// 游戏内容区域
.game-content {
  position: relative;
  flex: 1;
  padding: var(--space-xl) calc(32px * var(--ui-scale, 1));
  display: flex;
  flex-direction: column;
  gap: var(--space-xl);
  overflow: hidden;
}

.turn-layout {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

// 重ROLL 遮罩：仅覆盖主内容，不挡侧边栏
.regenerate-overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  border-radius: 8px;

  .regenerate-spin {
    font-size: 32px;
    opacity: 0.9;
  }

  span {
    font-size: 15px;
    font-weight: 500;
  }

  &.dark {
    background: rgba(3, 3, 3, 0.75);
    color: #e4e4e7;

    .regenerate-spin {
      color: #a1a1aa;
    }
  }

  &.light {
    background: rgba(250, 250, 250, 0.85);
    color: #27272a;

    .regenerate-spin {
      color: #71717a;
    }
  }
}

// 开场白生成中弹窗
.opening-generating-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;

  &.dark {
    background: rgba(3, 3, 3, 0.9);

    .opening-generating-content {
      i {
        color: #60a5fa;
      }

      .opening-generating-text {
        color: #e4e4e7;
      }

      .opening-generating-hint {
        color: #71717a;
      }
    }
  }

  &.light {
    background: rgba(250, 250, 250, 0.9);

    .opening-generating-content {
      i {
        color: #2563eb;
      }

      .opening-generating-text {
        color: #18181b;
      }

      .opening-generating-hint {
        color: #71717a;
      }
    }
  }
}

.opening-generating-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 48px;
  border-radius: 16px;

  i {
    font-size: 48px;
  }

  .opening-generating-text {
    font-size: 20px;
    font-weight: 600;
  }

  .opening-generating-hint {
    font-size: 14px;
  }
}

// 正文区域（重ROLL 时虚化）
.maintext-area {
  flex: 1;
  min-height: 0;
  transition: filter 0.2s ease;
  overflow-y: auto;
  padding-right: calc(6px * var(--ui-scale, 1));

  &.is-blurred {
    filter: blur(calc(4px * var(--ui-scale, 1)));
    pointer-events: none;
  }
}

.maintext-container {
  cursor: default;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;

  &.can-long-press {
    cursor: pointer;
  }
}

.maintext-content {
  font-size: calc(16px * var(--ui-scale, 1));
  line-height: 1.8;
  color: #e4e4e7;
  white-space: pre-wrap;
  word-wrap: break-word;
}

.dark .maintext-content {
  color: #e4e4e7;
}

.light .maintext-content {
  color: #27272a;
}

.maintext-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  min-height: 200px;
  color: #71717a;
  text-align: center;

  .hint {
    font-size: 12px;
    margin-top: 8px;
    color: #52525b;
  }
}

.light .maintext-placeholder {
  color: #a1a1aa;

  .hint {
    color: #d4d4d8;
  }
}

// 长按正文：上下文菜单
.context-menu.maintext-context-menu {
  position: fixed;
  z-index: 9999;
  min-width: 200px;
  border-radius: 8px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  overflow: hidden;

  .context-menu-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 12px;
    font-size: 13px;
    font-weight: 600;
  }

  .context-menu-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 18px;
    line-height: 1;
    padding: 0 4px;
    opacity: 0.8;

    &:hover {
      opacity: 1;
    }
  }

  .context-menu-item {
    display: block;
    width: 100%;
    padding: 10px 16px;
    text-align: left;
    border: none;
    background: none;
    cursor: pointer;
    font-size: 14px;
    transition: background 0.15s;

    &:hover:not(:disabled) {
      background: rgba(255, 255, 255, 0.08);
    }

    &:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }
  }
}

.maintext-context-menu.dark {
  background: rgba(24, 24, 27, 0.98);
  border: 1px solid rgba(63, 63, 70, 0.8);

  .context-menu-header,
  .context-menu-item {
    color: #e4e4e7;
  }
}

.maintext-context-menu.light {
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid rgba(0, 0, 0, 0.1);

  .context-menu-header,
  .context-menu-item {
    color: #27272a;
  }

  .context-menu-item:hover:not(:disabled) {
    background: rgba(0, 0, 0, 0.06);
  }
}

// 编辑正文模态框
.edit-maintext-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(4px);
}

.edit-maintext-modal {
  width: 100%;
  max-width: 800px;
  max-height: 90vh;
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.edit-maintext-modal.dark {
  background: #18181b;
  border: 1px solid rgba(63, 63, 70, 0.8);
}

.edit-maintext-modal.light {
  background: #fafafa;
  border: 1px solid rgba(0, 0, 0, 0.1);
}

.edit-maintext-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  flex-shrink: 0;

  h2 {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
  }

  .close-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 24px;
    line-height: 1;
    padding: 0 4px;
    opacity: 0.8;

    &:hover {
      opacity: 1;
    }
  }
}

.edit-maintext-modal.dark .edit-maintext-header {
  color: #e4e4e7;
  border-color: rgba(255, 255, 255, 0.1);

  .close-btn {
    color: #e4e4e7;
  }
}

.edit-maintext-modal.light .edit-maintext-header {
  color: #27272a;
  border-color: rgba(0, 0, 0, 0.1);

  .close-btn {
    color: #27272a;
  }
}

.edit-maintext-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}

.edit-maintext-textarea {
  width: 100%;
  min-height: 320px;
  padding: 12px;
  border-radius: 8px;
  font-size: 14px;
  line-height: 1.6;
  resize: vertical;
  outline: none;
  font-family: inherit;
}

.variable-reroll-hint {
  font-size: 13px;
  line-height: 1.6;
  opacity: 0.9;

  code {
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    font-size: 12px;
    padding: 2px 6px;
    border-radius: 6px;
    background: rgba(127, 127, 127, 0.15);
  }
}

// 右下角变量按钮
.variable-fab {
  position: absolute;
  right: var(--space-xl);
  bottom: calc(120px * var(--ui-scale, 1));
  z-index: 15;
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  padding: calc(10px * var(--ui-scale, 1)) var(--space-md);
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, background 0.15s ease, border-color 0.15s ease;
  font-size: calc(13px * var(--ui-scale, 1));
  user-select: none;

  &:hover {
    transform: translateY(calc(-1px * var(--ui-scale, 1)));
  }

  i {
    font-size: calc(14px * var(--ui-scale, 1));
  }
}

.variable-fab-text {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.variable-fab.dark {
  background: rgba(39, 39, 42, 0.85);
  border-color: rgba(63, 63, 70, 0.8);
  color: #e4e4e7;

  &:hover {
    background: rgba(63, 63, 70, 0.7);
  }
}

.variable-fab.light {
  background: rgba(255, 255, 255, 0.9);
  border-color: rgba(0, 0, 0, 0.12);
  color: #27272a;

  &:hover {
    background: rgba(244, 244, 245, 0.95);
  }
}

// =========================
// 响应式布局（手机/平板）
// =========================

// 平板及以下：去掉桌面端固定高度限制
@media (max-width: 1024px) {
  // 平板及以下：宽度自适应，但保留用户设置的高度
  .rule-modifier {
    max-width: 100%;
  }

  .sidebar,
  .middle-panel,
  .main-panel {
    max-height: var(--ui-max-height, none);
  }

  .middle-panel {
    width: min(90vw, 520px);
  }

  .panel-inner {
    width: 100%;
  }
}

// 手机端：底部导航 + 中间面板全屏抽屉 + 适配视口高度
@media (max-width: 768px) {
  .rule-modifier {
    max-width: 100%;
    width: 100%;
    margin: 0;
    // 手机端高度使用 CSS 变量，支持自定义高度
    height: var(--ui-max-height, 100dvh);
    max-height: var(--ui-max-height, 100dvh);
    // 为底部导航留出空间
    padding-bottom: 72px;
  }

  // Sidebar 变成底部栏
  .sidebar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    height: 72px;
    max-height: none;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    border-right: none;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    z-index: 50;
  }

  .light .sidebar {
    border-top-color: rgba(0, 0, 0, 0.08);
  }

  // 底部栏不显示 logo 区与分组布局，改为水平排列
  .sidebar-top .logo {
    display: none;
  }

  .sidebar-top,
  .sidebar-bottom {
    padding: 0;
    border: none;
  }

  .sidebar-top .nav-items {
    padding: 8px 10px;
    flex-direction: row;
    gap: 10px;
    align-items: center;
    justify-content: space-around;
    width: 100%;
  }

  // 底部栏按钮：仅图标为主，文字隐藏
  .nav-btn {
    padding: 10px 12px;
    border-radius: 14px;
  }

  .nav-label {
    display: none;
  }

  // Middle panel 变成全屏抽屉（覆盖正文）
  .middle-panel {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100dvh;
    max-height: none;
    z-index: 60;
    border-left: none;
    border-right: none;
    border-radius: 0;
  }

  .panel-inner {
    width: 100%;
  }

  .panel-content {
    padding: 16px 16px;
  }

  .panel-header {
    padding: 0 16px;
  }

  // 主面板占满宽度；输入区避免被底部导航遮挡
  .main-panel {
    max-height: none;
  }

  .input-area {
    padding-bottom: calc(24px + env(safe-area-inset-bottom));
  }

  // 右下角浮动按钮在手机上抬高一点，避免和底部栏/输入框打架
  .variable-fab {
    bottom: calc(152px * var(--ui-scale, 1));
    right: var(--space-lg);
  }
}

.edit-maintext-modal.dark .edit-maintext-textarea {
  background: rgba(39, 39, 42, 0.8);
  border: 1px solid rgba(63, 63, 70, 0.8);
  color: #e4e4e7;
}

.edit-maintext-modal.light .edit-maintext-textarea {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.15);
  color: #27272a;
}

.edit-maintext-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  flex-shrink: 0;
}

// 选项区域
.options-area {
  z-index: 12;
  margin-top: 0;
  flex-shrink: 0;
  padding-top: var(--space-md);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(calc(10px * var(--ui-scale, 1)));
}

.dark .options-area {
  border-color: rgba(255, 255, 255, 0.1);
  background: linear-gradient(
    to top,
    rgba(3, 3, 3, 0.92) 0%,
    rgba(3, 3, 3, 0.75) 65%,
    rgba(3, 3, 3, 0) 100%
  );
}

.light .options-area {
  border-color: rgba(0, 0, 0, 0.1);
  background: linear-gradient(
    to top,
    rgba(250, 250, 250, 0.96) 0%,
    rgba(250, 250, 250, 0.82) 65%,
    rgba(250, 250, 250, 0) 100%
  );
}

.options-title {
  font-size: calc(14px * var(--ui-scale, 1));
  font-weight: 500;
  color: #a1a1aa;
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.dark .options-title {
  color: #a1a1aa;
}

.light .options-title {
  color: #71717a;
}

.options-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  width: 100%;
  padding: calc(10px * var(--ui-scale, 1)) var(--space-md);
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;
  font-size: calc(14px * var(--ui-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  margin-bottom: var(--space-sm);

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
  }

  i {
    font-size: calc(12px * var(--ui-scale, 1));
    transition: transform 0.2s;
  }
}

.dark .options-toggle {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }
}

.light .options-toggle {
  border-color: rgba(0, 0, 0, 0.1);
  background: rgba(0, 0, 0, 0.05);
  color: #27272a;

  &:hover {
    background: rgba(0, 0, 0, 0.1);
  }
}

// 选项列表展开/折叠动画
.slide-enter-active,
.slide-leave-active {
  transition: all 0.3s ease;
  max-height: 500px;
  overflow: hidden;
}

.slide-enter-from,
.slide-leave-to {
  max-height: 0;
  opacity: 0;
}

.options-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  overflow: hidden;
}

.option-btn {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateX(calc(4px * var(--ui-scale, 1)));
  }
}

.dark .option-btn {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
  }
}

.light .option-btn {
  border-color: rgba(0, 0, 0, 0.1);
  background: rgba(0, 0, 0, 0.05);
  color: #27272a;

  &:hover {
    background: rgba(0, 0, 0, 0.1);
    border-color: rgba(0, 0, 0, 0.2);
  }
}

.option-id {
  display: flex;
  align-items: center;
  justify-content: center;
  width: calc(28px * var(--ui-scale, 1));
  height: calc(28px * var(--ui-scale, 1));
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.1);
  font-size: calc(12px * var(--ui-scale, 1));
  font-weight: 600;
  flex-shrink: 0;
}

.dark .option-id {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.light .option-id {
  background: rgba(0, 0, 0, 0.1);
  color: #18181b;
}

.option-text {
  font-size: calc(14px * var(--ui-scale, 1));
  line-height: 1.5;
}

// 阅读模式和读档模式
.reader-mode,
.save-mode {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.mode-header {
  padding: 16px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 16px;

  h3 {
    font-size: 18px;
    font-weight: 600;
    margin-bottom: 4px;
  }

  p {
    font-size: 13px;
    color: #a1a1aa;
  }
}

.dark .mode-header {
  border-color: rgba(255, 255, 255, 0.1);

  h3 { color: #f4f4f5; }
  p { color: #a1a1aa; }
}

.light .mode-header {
  border-color: rgba(0, 0, 0, 0.1);

  h3 { color: #18181b; }
  p { color: #71717a; }
}

.history-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.history-item {
  padding: 16px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.02);

  .history-meta {
    font-size: 12px;
    color: #71717a;
    margin-bottom: 8px;
    font-family: monospace;
    display: flex;
    align-items: center;
    gap: 8px;

    .turn-badge {
      display: inline-flex;
      align-items: center;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 11px;
      font-weight: 600;
      font-family: -apple-system, BlinkMacSystemFont, sans-serif;
      background: rgba(96, 165, 250, 0.15);
      color: #60a5fa;
    }
  }

  .history-content {
    font-size: 14px;
    line-height: 1.6;
    color: #e4e4e7;
    white-space: pre-wrap;
  }
}

.dark .history-item {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.02);

  .history-meta { color: #71717a; }
  .history-content { color: #e4e4e7; }
}

.light .history-item {
  border-color: rgba(0, 0, 0, 0.1);
  background: #fff;

  .history-meta {
    color: #a1a1aa;

    .turn-badge {
      background: rgba(37, 99, 235, 0.1);
      color: #2563eb;
    }
  }
  .history-content { color: #27272a; }
}

.save-item {
  cursor: pointer;
  transition: all 0.2s;
  position: relative;

  &:hover {
    border-color: rgba(59, 130, 246, 0.5);
    background: rgba(59, 130, 246, 0.1);
  }

  .branch-hint {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    padding-top: var(--space-md);
    border-top: 1px dashed rgba(255, 255, 255, 0.1);
    font-size: 12px;
    color: #3b82f6;

    i {
      font-size: 14px;
    }
  }
}

.dark .save-item {
  &:hover {
    border-color: rgba(96, 165, 250, 0.5);
    background: rgba(96, 165, 250, 0.1);
  }

  .branch-hint {
    border-color: rgba(255, 255, 255, 0.1);
    color: #60a5fa;
  }
}

.light .save-item {
  &:hover {
    border-color: rgba(37, 99, 235, 0.5);
    background: rgba(37, 99, 235, 0.1);
  }

  .branch-hint {
    border-color: rgba(0, 0, 0, 0.1);
    color: #2563eb;
  }
}

.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: #71717a;
  font-size: 14px;
  line-height: 1.6;

  small {
    display: block;
    margin-top: 8px;
    font-size: 12px;
    opacity: 0.8;
  }
}

.dark .empty-state {
  color: #71717a;

  small {
    color: #52525b;
  }
}

.light .empty-state {
  color: #a1a1aa;

  small {
    color: #d4d4d8;
  }
}

.log-container {
  flex: 1;
  overflow-y: auto;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.input-area {
  padding: var(--space-lg) calc(32px * var(--ui-scale, 1));
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.dark .input-area {
  background: rgba(0, 0, 0, 0.2);
  border-color: rgba(255, 255, 255, 0.05);
}

.light .input-area {
  background: rgba(255, 255, 255, 0.5);
  border-color: rgba(0, 0, 0, 0.05);
}

// 输入框 + 发送：一体条（flex），避免按钮浮在框内产生缝隙
.input-wrapper {
  display: flex;
  align-items: stretch;
  max-width: calc(1000px * var(--ui-scale, 1));
  margin: 0 auto;
  border-radius: var(--radius-xl);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  transition: box-shadow 0.2s, border-color 0.2s;

  &:focus-within {
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.25);
    border-color: rgba(255, 255, 255, 0.2);
  }

  textarea {
    flex: 1;
    min-width: 0;
    width: auto;
    border: none;
    border-radius: 0;
    padding: var(--space-md) var(--space-md) var(--space-md) var(--space-xl);
    font-size: calc(15px * var(--ui-scale, 1));
    line-height: 1.5;
    resize: none;
    outline: none;
    background: transparent;
    color: inherit;
    transition: color 0.2s, opacity 0.2s;

    &::placeholder {
      color: #52525b;
    }

    &:disabled {
      opacity: 0.75;
      cursor: not-allowed;
    }
  }
}

.dark .input-wrapper {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #fff;

  &:focus-within {
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.2);
    border-color: rgba(255, 255, 255, 0.22);
  }

  textarea {
    &::placeholder {
      color: #52525b;
    }

    &:disabled {
      color: #71717a;
    }
  }
}

.light .input-wrapper {
  border-color: rgba(0, 0, 0, 0.1);
  background: #fff;
  color: #18181b;

  &:focus-within {
    box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.18);
    border-color: rgba(0, 0, 0, 0.18);
  }

  textarea {
    &::placeholder {
      color: #a1a1aa;
    }

    &:disabled {
      color: #a1a1aa;
    }
  }
}

// 发送按钮：贴在输入条右侧，与框共用外轮廓
.send-btn {
  position: static;
  transform: none;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  min-width: calc(72px * var(--ui-scale, 1));
  padding: 0 var(--space-lg);
  margin: 0;
  border: none;
  border-radius: 0;
  border-left: 1px solid rgba(255, 255, 255, 0.12);
  cursor: pointer;
  font-size: calc(14px * var(--ui-scale, 1));
  font-weight: 500;
  transition: background 0.2s, color 0.2s;

  &:disabled {
    cursor: not-allowed;
    opacity: 0.7;
    background: rgba(47, 54, 61, 0.6) !important;
    color: #71717a !important;
  }
}

.main-panel.dark .send-btn {
  background: #363f46;
  color: #a9a9a9;
  border-left-color: rgba(255, 255, 255, 0.12);

  &:hover:not(:disabled) {
    background: #434d58;
    color: #d4d4d8;
  }

  &:disabled {
    background: rgba(47, 54, 61, 0.8) !important;
    color: #71717a !important;
  }
}

.main-panel.light .send-btn {
  background: #e5e7eb;
  color: #6b7280;
  border-left-color: rgba(0, 0, 0, 0.08);

  &:hover:not(:disabled) {
    background: #d1d5db;
    color: #374151;
  }

  &:disabled {
    background: rgba(229, 231, 235, 0.8) !important;
    color: #9ca3af !important;
  }
}

// 生成中动画提示
.generating-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-md);
  font-size: calc(14px * var(--ui-scale, 1));
  color: #60a5fa;

  i {
    animation: pulse 1.5s ease-in-out infinite;
  }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

// Modal（需高于 .middle-panel 手机抽屉 z-index: 60，否则点「编辑」弹窗在抽屉下方看不见）
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(4px);
}

.modal-content {
  width: 100%;
  max-width: 600px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);

  &.modal-enter-active,
  &.modal-leave-active {
    transition: all 0.3s ease;
  }

  &.modal-enter-from,
  &.modal-leave-to {
    opacity: 0;
    transform: scale(0.95) translateY(20px);
  }
}

.dark .modal-content {
  background: #080808;
}

.light .modal-content {
  background: #fff;
  border-color: rgba(0, 0, 0, 0.1);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.02);

  h2 {
    font-size: 18px;
    font-weight: 500;
  }

  .close-btn {
    background: transparent;
    border: none;
    font-size: 20px;
    cursor: pointer;
    transition: color 0.2s;
  }
}

.dark .modal-header {
  border-color: rgba(255, 255, 255, 0.05);
  color: #fff;

  .close-btn {
    color: #71717a;

    &:hover { color: #fff; }
  }
}

.light .modal-header {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;

  .close-btn {
    color: #a1a1aa;

    &:hover { color: #18181b; }
  }
}

.rule-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;

  h2 {
    flex: 1;
    text-align: center;
    margin: 0;
  }
}

.btn-complete {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  background: #22c55e;
  color: #fff;
  flex-shrink: 0;

  &:hover {
    background: #16a34a;
  }
}

.btn-cancel {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  background: #ef4444;
  color: #fff;
  flex-shrink: 0;

  &:hover {
    background: #dc2626;
  }
}

.rule-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-label {
  font-size: 14px;
  font-weight: 500;
  color: #a1a1aa;
}

.dark .form-label {
  color: #a1a1aa;
}

.light .form-label {
  color: #71717a;
}

.form-input,
.form-textarea {
  width: 100%;
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 14px;
  outline: none;
  font-family: inherit;
}

.form-textarea {
  resize: vertical;
  min-height: 120px;
}

.dark .form-input,
.dark .form-textarea {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #fff;

  &::placeholder {
    color: #71717a;
  }
}

.light .form-input,
.light .form-textarea {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.15);
  color: #18181b;

  &::placeholder {
    color: #a1a1aa;
  }
}

.modal-body {
  padding: 24px;
  min-height: 300px;
}

.modal-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 16px;
  height: 100%;

  .spin-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(255, 255, 255, 0.1);

    i {
      font-size: 32px;
      color: #52525b;
    }
  }

  h3 {
    font-size: 16px;
    font-weight: 500;
    color: #e4e4e7;
  }

  p {
    font-size: 14px;
    color: #71717a;
    max-width: 300px;

