  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.dark .modal-footer {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .modal-footer {
  border-color: rgba(0, 0, 0, 0.05);
  background: rgba(0, 0, 0, 0.02);
}

.btn-secondary,
.btn-primary {
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
