  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.05);
  }
}

.light .btn-secondary {
  color: #71717a;

  &:hover {
    color: #18181b;
    background: rgba(0, 0, 0, 0.05);
  }
}

.btn-primary {
  color: #fff;
  background: rgba(255, 255, 255, 0.15);

  &:hover {
    background: rgba(255, 255, 255, 0.2);
  }
}

.light .btn-primary {
  color: #fff;
  background: #18181b;

  &:hover {
    background: #27272a;
  }
}

// 末尾玩家楼层提示（叠在标签弹窗之上，避免被挡）
.orphan-user-floor-overlay {
  z-index: 10002;
}

.orphan-user-floor-modal {
  max-width: 440px;
  width: 100%;
}

.orphan-user-floor-intro,
.orphan-user-floor-hint {
  font-size: 14px;
  line-height: 1.55;
  margin: 0 0 12px;
  color: #a1a1aa;
