.light .orphan-user-floor-intro,
.light .orphan-user-floor-hint {
  color: #52525b;
}

.orphan-user-floor-meta {
  font-size: 13px;
  margin: 0 0 12px;
  color: #e4e4e7;

  code {
    font-family: ui-monospace, monospace;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.08);
