
.regional-rules-panel {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;

  .desc {
    font-size: 14px;
    color: #a1a1aa;
  }
}

.action-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }
}

:global(.light) .action-btn {
  background: rgba(0, 0, 0, 0.05);
  color: #27272a;

  &:hover {
    background: rgba(0, 0, 0, 0.1);
  }
}

.loading-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 24px;
  color: #71717a;
  font-size: 14px;

  i {
    font-size: 20px;
  }
}

:global(.light) .loading-state {
  color: #a1a1aa;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
  gap: 12px;

  i {
    font-size: 48px;
    color: #52525b;
    opacity: 0.5;
  }

  p {
    font-size: 16px;
    font-weight: 500;
    color: #e4e4e7;
    margin: 0;
  }

  .hint {
    font-size: 13px;
    color: #71717a;
  }
}

:global(.light) .empty-state {
  i {
    color: #a1a1aa;
  }

  p {
    color: #27272a;
  }

  .hint {
    color: #a1a1aa;
  }
}

/* 归档区 */
.archive-section {
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.02);
  overflow: hidden;
}

:global(.light) .archive-section {
  border-color: rgba(0, 0, 0, 0.1);
  background: rgba(0, 0, 0, 0.02);
}

.archive-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border: none;
  background: transparent;
  color: #a1a1aa;
  font-size: 14px;
  cursor: pointer;
  text-align: left;

  .toggle-icon {
    margin-left: auto;
    transition: transform 0.2s;
  }

  &.open .toggle-icon {
    transform: rotate(180deg);
  }
}

.archive-content {
  padding: 0 16px 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

:global(.light) .archive-content {
  border-color: rgba(0, 0, 0, 0.05);
}

.archive-group {
  margin-top: 12px;

  &:first-child {
    margin-top: 12px;
  }
}

.archive-group-title {
  font-size: 12px;
  color: #71717a;
  margin-bottom: 6px;
}

.archive-rule-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  margin-bottom: 4px;
}

:global(.light) .archive-rule-row {
  background: rgba(0, 0, 0, 0.04);
}

.archive-rule-desc {
  flex: 1;
  font-size: 13px;
  color: #d4d4d8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:global(.light) .archive-rule-desc {
  color: #3f3f46;
}

.restore-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  font-size: 12px;
  color: #a1a1aa;
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  flex-shrink: 0;

  &:hover {
    color: #22c55e;
    background: rgba(34, 197, 94, 0.1);
  }
}

/* 区域卡片 */
.regions-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
}

.region-card-wrap {
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.02);
}

:global(.light) .region-card-wrap {
  border-color: rgba(0, 0, 0, 0.1);
  background: #fff;
}

.region-card .card-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border: none;
  background: rgba(255, 255, 255, 0.02);
  color: #fff;
  font-size: 14px;
  cursor: pointer;
  text-align: left;

  .title-group {
    display: flex;
    align-items: center;
    gap: 12px;

    i {
      font-size: 20px;
      color: #a1a1aa;
    }

    h3 {
      font-size: 16px;
      font-weight: 500;
      margin: 0;
    }
  }

  .rule-count {
    margin-left: auto;
    font-size: 12px;
    color: #71717a;
  }

  .header-chevron {
    font-size: 12px;
    color: #71717a;
    transition: transform 0.2s;
  }

  &.expanded .header-chevron {
    transform: rotate(180deg);
  }
}

:global(.light) .region-card .card-header {
  background: rgba(0, 0, 0, 0.02);

  .title-group h3 {
    color: #18181b;
  }
}

.card-body {
  padding: 16px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

:global(.light) .card-body {
  border-color: rgba(0, 0, 0, 0.05);
}

.rule-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);

  &:last-child {
    border-bottom: none;
  }
}

:global(.light) .rule-row {
  border-color: rgba(0, 0, 0, 0.05);
}

.rule-desc {
  flex: 1;
  font-size: 14px;
  color: #a1a1aa;
  line-height: 1.5;
}

:global(.light) .rule-desc {
  color: #71717a;
}

.rule-actions .action {
  padding: 6px 10px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: #71717a;
  cursor: pointer;
  flex-shrink: 0;

  &:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #e4e4e7;
  }
}

:global(.light) .rule-actions .action:hover {
  background: rgba(0, 0, 0, 0.06);
  color: #18181b;
}

.card-footer {
  padding-top: 12px;
  margin-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  gap: 8px;
}

:global(.light) .card-footer {
  border-color: rgba(0, 0, 0, 0.05);
}

.footer-btn {
  flex: 1;
  padding: 10px;
  border-radius: 8px;
  font-size: 14px;
  color: #a1a1aa;
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.05);
  }

  &.delete:hover {
    color: #ef4444;
    background: rgba(239, 68, 68, 0.1);
  }
}

:global(.light) .footer-btn {
  color: #71717a;

  &:hover {
    color: #18181b;
    background: rgba(0, 0, 0, 0.05);
  }
}
